@PostMapping("/login")
public User loginUser(String username, String password) {
    // vulnerable: direct string concatenation allows SQL injection
    String query = "SELECT * FROM users WHERE username='" + username + 
                   "' AND password='" + password + "'";

    try (Connection conn = dataSource.getConnection();
         Statement stmt = conn.createStatement()) {
        ResultSet rs = stmt.executeQuery(query);
        // attacker can input: admin' OR '1'='1
        // which makes query always return true
        if (rs.next()) {
            return new User(rs.getString("username"));
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return null;
}
***
// Controller endpoint for user login - secure version
@PostMapping("/login")
public User loginUserSecure(String username, String password) {
    // fixed: using prepared statement prevents SQL injection
    String query = "SELECT * FROM users WHERE username = ? AND password = ?";

    try (Connection conn = dataSource.getConnection();
         PreparedStatement pstmt = conn.prepareStatement(query)) {
        // parameters are properly escaped
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();
        if (rs.next()) {
            return new User(rs.getString("username"));
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return null;
}

